212	    public void updateRows(List<MediaGroup> mediaGroups) {
213	        if (getView() == null) { // starting from outside (e.g. MediaServiceManager)
214	            mChannelId = null;
215	            mPendingGroups.add(mediaGroups);
216	            getViewManager().startView(ChannelView.class);
217	            return;
218	        }
219	
220	        // The view could be running in the background
221	        getViewManager().startView(ChannelView.class);
222	
223	        for (MediaGroup mediaGroup : mediaGroups) {
224	            if (mediaGroup.getMediaItems() == null) {
225	                Log.e(TAG, "updateRowsHeader: MediaGroup is empty. Group Name: " + mediaGroup.getTitle());
226	                continue;
227	            }
228	
229	            VideoGroup group = VideoGroup.from(mediaGroup);
230	            getView().update(group);
231	            mBrowseProcessor.process(group);
232	        }
233	
234	        getView().showProgressBar(false);
235	    }
