237	    private void continueGroup(VideoGroup group) {
238	        boolean scrollInProgress = mScrollAction != null && !mScrollAction.isDisposed();
239	
240	        if (scrollInProgress) {
241	            return;
242	        }
243	
244	        if (getView() == null) {
245	            Log.e(TAG, "Can't continue group. The view is null.");
246	            return;
247	        }
248	
249	        if (group == null) {
250	            Log.e(TAG, "Can't continue group. The group is null.");
251	            return;
252	        }
253	
254	        Log.d(TAG, "continueGroup: start continue group: " + group.getTitle());
255	
256	        getView().showProgressBar(true);
257	
258	        MediaGroup mediaGroup = group.getMediaGroup();
259	
260	        mScrollAction = getContentService().continueGroupObserve(mediaGroup)
261	                .subscribe(
262	                        continueMediaGroup -> {
263	                            VideoGroup newGroup = VideoGroup.from(group, continueMediaGroup);
264	                            getView().update(newGroup);
265	                            mBrowseProcessor.process(newGroup);
266	                        },
267	                        error -> {
268	                            Log.e(TAG, "continueGroup error: %s", error.getMessage());
269	                            if (getView() != null) {

